CREATE SCHEMA IF NOT EXISTS activity;

CREATE TABLE IF NOT EXISTS activity.activities (
    id UUID NOT NULL DEFAULT gen_random_uuid(),
    company_id UUID NOT NULL,
    subject TEXT NOT NULL,
    activity_type activity_type NOT NULL DEFAULT 'whatsapp',
    direction activity_direction,
    lead_id UUID,
    opportunity_id UUID,
    party_id UUID,
    status activity_status NOT NULL DEFAULT 'planned',
    scheduled_at TIMESTAMPTZ,
    occurred_at TIMESTAMPTZ,
    assignee_id UUID,
    outcome TEXT,
    notes TEXT,
    metadata JSONB NOT NULL DEFAULT '{"created_at":null,"updated_at":null,"deleted_at":null,"created_by":null,"updated_by":null,"deleted_by":null}'::jsonb,
    PRIMARY KEY (id)
);

CREATE INDEX IF NOT EXISTS idx_activities_company_id_status ON activity.activities (company_id, status);

CREATE INDEX IF NOT EXISTS idx_activities_lead_id ON activity.activities (lead_id);

