-- GIN index for audit metadata JSONB queries
CREATE INDEX IF NOT EXISTS idx_activities_metadata_gin ON activity.activities USING GIN (metadata);
CREATE INDEX IF NOT EXISTS idx_activities_metadata_deleted_at ON activity.activities ((metadata->>'deleted_at'));
CREATE INDEX IF NOT EXISTS idx_activities_metadata_created_at ON activity.activities ((metadata->>'created_at'));
CREATE INDEX IF NOT EXISTS idx_activities_metadata_updated_at ON activity.activities ((metadata->>'updated_at'));

-- Triggers for automatic metadata timestamp management
-- Automatically sets created_at on INSERT and updated_at on UPDATE

-- Function to set metadata->'created_at' on INSERT
CREATE OR REPLACE FUNCTION activity.activities_audit_timestamp() RETURNS trigger AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        NEW.metadata = jsonb_set(NEW.metadata::jsonb, '{created_at}', to_jsonb(NOW()));
        NEW.metadata = jsonb_set(NEW.metadata::jsonb, '{updated_at}', to_jsonb(NOW()));
    ELSIF TG_OP = 'UPDATE' THEN
        NEW.metadata = jsonb_set(NEW.metadata::jsonb, '{updated_at}', to_jsonb(NOW()));
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- Trigger to set timestamps on INSERT
DROP TRIGGER IF EXISTS activities_insert_audit ON activity.activities;
CREATE TRIGGER activities_insert_audit BEFORE INSERT ON activity.activities
    FOR EACH ROW EXECUTE FUNCTION activity.activities_audit_timestamp();

-- Trigger to set updated_at on UPDATE
DROP TRIGGER IF EXISTS activities_update_audit ON activity.activities;
CREATE TRIGGER activities_update_audit BEFORE UPDATE ON activity.activities
    FOR EACH ROW EXECUTE FUNCTION activity.activities_audit_timestamp();
